; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpc, starts in normal mode
; ============================================================

			org #4000

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; 1: n = 10 : m = -3
			dw kw_ltov, 10, var_n
			dw kw_ltov, -3, var_m

			; 2: FOR i = 1 TO 10 : NEXT
			dw kw_ltov, 1, var_i
for1_t:
			dw kw_next1l_n, var_i, 10, for1_t
for1_e:

			; 3: PRINT "a"; i
			dw kw_printzoscii
			dw glyph_61, 0		; "a"
			dw kw_printint, var_i
			dw kw_printnl

			; 4: FOR i = 1 TO n : s = s + i : NEXT : PRINT "b"; s; i
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_n, for2_l
			dw kw_forupv_n, var_i, for2_l, for2_e
for2_t:
			dw kw_add, var_s, var_i, var_s
			dw kw_next1v_n, var_i, for2_l, for2_t
for2_e:
			dw kw_printzoscii
			dw glyph_62, 0		; "b"
			dw kw_printint, var_s
			dw kw_printint, var_i
			dw kw_printnl

			; 5: FOR i = n TO 1 STEP -1 : PRINT i; : NEXT : PRINT
			dw kw_vtov, var_n, var_i
			dw kw_fordnl_n, var_i, 1, for3_e
for3_t:
			dw kw_printint, var_i
			dw kw_nextdnl_n, var_i, -1, 1, for3_t
for3_e:
			dw kw_printnl

			; 6: FOR i = 1 TO n STEP 3 : PRINT i; : NEXT : PRINT
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_n, for4_l
			dw kw_forupv_n, var_i, for4_l, for4_e
for4_t:
			dw kw_printint, var_i
			dw kw_nextupv_n, var_i, 3, for4_l, for4_t
for4_e:
			dw kw_printnl

			; 7: FOR i = 10 TO m STEP -4 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, 10, var_i
			dw kw_vtov, var_m, for5_l
			dw kw_fordnv_n, var_i, for5_l, for5_e
for5_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_nextdnv_n, var_i, -4, for5_l, for5_t
for5_e:
			dw kw_printnl

			; 8: FOR i = 5 TO 1 : PRINT "x" : NEXT : PRINT "c"; i
			dw kw_ltov, 5, var_i
			dw for6_e_go
for6_t:
			dw kw_printzoscii
			dw glyph_78, 1, 0		; "x\n"
			dw kw_next1l_n, var_i, 1, for6_t
for6_e:
			dw kw_printzoscii
			dw glyph_63, 0		; "c"
			dw kw_printint, var_i
			dw kw_printnl

			; 9: FOR i = n TO 1 : PRINT "x" : NEXT : PRINT "d"; i
			dw kw_vtov, var_n, var_i
			dw kw_forupl_n, var_i, 1, for7_e
for7_t:
			dw kw_printzoscii
			dw glyph_78, 1, 0		; "x\n"
			dw kw_next1l_n, var_i, 1, for7_t
for7_e:
			dw kw_printzoscii
			dw glyph_64, 0		; "d"
			dw kw_printint, var_i
			dw kw_printnl

			; 10: FOR i = m TO -1 : PRINT i; : NEXT : PRINT
			dw kw_vtov, var_m, var_i
			dw kw_forupl_n, var_i, -1, for8_e
for8_t:
			dw kw_printint, var_i
			dw kw_next1l_n, var_i, -1, for8_t
for8_e:
			dw kw_printnl

			; 11: FOR i = 254 TO 258 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, 254, var_i
for9_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_next1l_n, var_i, 258, for9_t
for9_e:
			dw kw_printnl

			; 12: FOR i = -2 TO 2 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, -2, var_i
for10_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_next1l_n, var_i, 2, for10_t
for10_e:
			dw kw_printnl

			; 13: st = 2 : FOR i = 1 TO 6 STEP st : PRINT i; : NEXT : PRINT
			dw kw_ltov, 2, var_st
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_st, for11_s
			dw kw_ltov, 6, for11_l
			dw kw_forentry_n, var_i, for11_s, for11_l, for11_e
for11_t:
			dw kw_printint, var_i
			dw kw_fornext_n, var_i, for11_s, for11_l, for11_t
for11_e:
			dw kw_printnl
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

for6_e_go:			ld sp, for6_e
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
var_m:			dw 0
var_i:			dw 0
for2_l:			dw 0
var_s:			dw 0
for4_l:			dw 0
for5_l:			dw 0
var_st:			dw 0
for11_s:			dw 0
for11_l:			dw 0

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_61			equ ntc_font + 520		; "a"
glyph_62			equ ntc_font + 528		; "b"
glyph_63			equ ntc_font + 536		; "c"
glyph_64			equ ntc_font + 544		; "d"
glyph_78			equ ntc_font + 704		; "x"

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared
; ------------------------------------------------------------
; Scratch space
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)
ntc_gnlo:		db 0			; ntc_getn: low byte
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)
ntc_lead:		db 0			; printint: digit seen
ntc_icnt:		db 0			; gets: chars typed
ntc_sptr:		dw 0			; printbuf: text pointer
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done
ntc_ivar:		dw 0			; inputint / inkey: dest var
ntc_aptr:		dw 0			; atoi: text pointer
ntc_numbuf:		ds 12			; printint / long print: digits
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again)
ntc_for_le_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_forupl (normal mode copy) ntc_for_jump
;kw_forupl, <var>, <literal limit>, <endlabel>
;  FOR entry, counting up: skip the loop if var > limit
kw_forupl_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_for_gt_n

;## kw_forupv (normal mode copy) ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_gt_n

;## kw_fordnl (normal mode copy) ntc_for_jump
;kw_fordnl, <var>, <literal limit>, <endlabel>
;  FOR entry, counting down: skip the loop if var < limit
kw_fordnl_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_for_lt_n

;## kw_fordnv (normal mode copy) ntc_for_jump
;kw_fordnv, <var>, <limit var>, <endlabel>
kw_fordnv_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_lt_n

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			jp ntc_for_le_n

;## kw_next1v (normal mode copy) ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1v_nc_n
			inc (hl)
ntc_n1v_nc_n:
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_le_n

;## ntc_nextadd
; var += literal step. Pops var and step. Leaves DE = new value.
ntc_nextadd:
			pop bc				; var
			pop hl				; step
			ld a, (bc)
			ld e, a
			inc bc
			ld a, (bc)
			ld d, a
			add hl, de
			ex de, hl			; DE = new value
			ld a, d
			ld (bc), a
			dec bc
			ld a, e
			ld (bc), a
			jp (ix)

;## kw_nextupv (normal mode copy) ntc_nextadd ntc_for_jump
;kw_nextupv, <var>, <literal step>, <limit var>, <toplabel>
kw_nextupv_n:
			ld ix, ntc_nuv_back_n
			jp ntc_nextadd
ntc_nuv_back_n:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_le_n

;## kw_nextdnl (normal mode copy) ntc_nextadd ntc_for_jump
;kw_nextdnl, <var>, <literal step>, <literal limit>, <toplabel>
;  NEXT for a negative STEP: add, back to the top while var >= limit
kw_nextdnl_n:
			ld ix, ntc_ndl_back_n
			jp ntc_nextadd
ntc_ndl_back_n:
			pop hl
			jp ntc_for_ge_n

;## kw_nextdnv (normal mode copy) ntc_nextadd ntc_for_jump
;kw_nextdnv, <var>, <literal step>, <limit var>, <toplabel>
kw_nextdnv_n:
			ld ix, ntc_ndv_back_n
			jp ntc_nextadd
ntc_ndv_back_n:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_ge_n

;## kw_forentry (normal mode copy)
;kw_forentry, <var>, <stepvar>, <limvar>, <endlabel>
;  skip the loop if var is already past lim for the step sign
kw_forentry_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld b, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			bit 7, b
			jr nz, ntc_fe_neg_n
			or a
			sbc hl, de
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_fe_neg_n:
			ex de, hl
			or a
			sbc hl, de
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_fornext (normal mode copy)
;kw_fornext, <var>, <stepvar>, <limvar>, <toplabel>
;  var += step, loop back while var has not passed lim
kw_fornext_n:
			pop ix
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld l, (ix+0)
			ld h, (ix+1)
			add hl, de
			ld (ix+0), l
			ld (ix+1), h
			ld b, d
			ex de, hl
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			bit 7, b
			jr nz, ntc_fn_neg_n
			or a
			sbc hl, de
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_fn_neg_n:
			ex de, hl
			or a
			sbc hl, de
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn

; ============================================================
; Assignment
; ============================================================

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_printbuf ntc_data ntc_font ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			sub 32
			jr c, ntc_pb_bad
			cp 95
			jr c, ntc_pb_ok
ntc_pb_bad:
			ld a, '?' - 32
ntc_pb_ok:
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld de, ntc_font
			add hl, de
			ex de, hl
			ld ix, ntc_printbuf
			jp ntc_plat_putglyph

;## kw_printzoscii ntc_data ntc_font ntc_plat_screen
;kw_printzoscii / dw glyph, glyph, ..., 0  - ZOSCII text inline in the thread
;  each word points at an 8 byte glyph bitmap. 1 = newline, 0 = end.
kw_printzoscii:
			pop de
			ld a, d
			or a
			jr z, ntc_pz_ctl
			ld ix, kw_printzoscii
			jp ntc_plat_putglyph
ntc_pz_ctl:
			or e
			ret z
			ld ix, kw_printzoscii
			jp ntc_plat_newline

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_scrinit ntc_data ntc_plat_screen
;kw_scrinit  - first word of any program that prints or reads keys:
;  mode 1, ROMs off, clear screen
kw_scrinit:
			ld a, 1
			ld ix, ntc_next
			jp ntc_plat_mode

;## ntc_font
; 8x8 font, chars 32-126, 8 bytes each, bit 7 = leftmost pixel
; from font8x8_basic by Daniel Hepper (public domain, IBM VGA based)
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:
			db #00, #00, #00, #00, #00, #00, #00, #00		; 32  
			db #18, #3C, #3C, #18, #18, #00, #18, #00		; 33 !
			db #6C, #6C, #00, #00, #00, #00, #00, #00		; 34 "
			db #6C, #6C, #FE, #6C, #FE, #6C, #6C, #00		; 35 #
			db #30, #7C, #C0, #78, #0C, #F8, #30, #00		; 36 $
			db #00, #C6, #CC, #18, #30, #66, #C6, #00		; 37 %
			db #38, #6C, #38, #76, #DC, #CC, #76, #00		; 38 &
			db #60, #60, #C0, #00, #00, #00, #00, #00		; 39 '
			db #18, #30, #60, #60, #60, #30, #18, #00		; 40 (
			db #60, #30, #18, #18, #18, #30, #60, #00		; 41 )
			db #00, #66, #3C, #FF, #3C, #66, #00, #00		; 42 *
			db #00, #30, #30, #FC, #30, #30, #00, #00		; 43 +
			db #00, #00, #00, #00, #00, #30, #30, #60		; 44 ,
			db #00, #00, #00, #FC, #00, #00, #00, #00		; 45 -
			db #00, #00, #00, #00, #00, #30, #30, #00		; 46 .
			db #06, #0C, #18, #30, #60, #C0, #80, #00		; 47 /
			db #7C, #C6, #CE, #DE, #F6, #E6, #7C, #00		; 48 0
			db #30, #70, #30, #30, #30, #30, #FC, #00		; 49 1
			db #78, #CC, #0C, #38, #60, #CC, #FC, #00		; 50 2
			db #78, #CC, #0C, #38, #0C, #CC, #78, #00		; 51 3
			db #1C, #3C, #6C, #CC, #FE, #0C, #1E, #00		; 52 4
			db #FC, #C0, #F8, #0C, #0C, #CC, #78, #00		; 53 5
			db #38, #60, #C0, #F8, #CC, #CC, #78, #00		; 54 6
			db #FC, #CC, #0C, #18, #30, #30, #30, #00		; 55 7
			db #78, #CC, #CC, #78, #CC, #CC, #78, #00		; 56 8
			db #78, #CC, #CC, #7C, #0C, #18, #70, #00		; 57 9
			db #00, #30, #30, #00, #00, #30, #30, #00		; 58 :
			db #00, #30, #30, #00, #00, #30, #30, #60		; 59 ;
			db #18, #30, #60, #C0, #60, #30, #18, #00		; 60 <
			db #00, #00, #FC, #00, #00, #FC, #00, #00		; 61 =
			db #60, #30, #18, #0C, #18, #30, #60, #00		; 62 >
			db #78, #CC, #0C, #18, #30, #00, #30, #00		; 63 ?
			db #7C, #C6, #DE, #DE, #DE, #C0, #78, #00		; 64 @
			db #30, #78, #CC, #CC, #FC, #CC, #CC, #00		; 65 A
			db #FC, #66, #66, #7C, #66, #66, #FC, #00		; 66 B
			db #3C, #66, #C0, #C0, #C0, #66, #3C, #00		; 67 C
			db #F8, #6C, #66, #66, #66, #6C, #F8, #00		; 68 D
			db #FE, #62, #68, #78, #68, #62, #FE, #00		; 69 E
			db #FE, #62, #68, #78, #68, #60, #F0, #00		; 70 F
			db #3C, #66, #C0, #C0, #CE, #66, #3E, #00		; 71 G
			db #CC, #CC, #CC, #FC, #CC, #CC, #CC, #00		; 72 H
			db #78, #30, #30, #30, #30, #30, #78, #00		; 73 I
			db #1E, #0C, #0C, #0C, #CC, #CC, #78, #00		; 74 J
			db #E6, #66, #6C, #78, #6C, #66, #E6, #00		; 75 K
			db #F0, #60, #60, #60, #62, #66, #FE, #00		; 76 L
			db #C6, #EE, #FE, #FE, #D6, #C6, #C6, #00		; 77 M
			db #C6, #E6, #F6, #DE, #CE, #C6, #C6, #00		; 78 N
			db #38, #6C, #C6, #C6, #C6, #6C, #38, #00		; 79 O
			db #FC, #66, #66, #7C, #60, #60, #F0, #00		; 80 P
			db #78, #CC, #CC, #CC, #DC, #78, #1C, #00		; 81 Q
			db #FC, #66, #66, #7C, #6C, #66, #E6, #00		; 82 R
			db #78, #CC, #E0, #70, #1C, #CC, #78, #00		; 83 S
			db #FC, #B4, #30, #30, #30, #30, #78, #00		; 84 T
			db #CC, #CC, #CC, #CC, #CC, #CC, #FC, #00		; 85 U
			db #CC, #CC, #CC, #CC, #CC, #78, #30, #00		; 86 V
			db #C6, #C6, #C6, #D6, #FE, #EE, #C6, #00		; 87 W
			db #C6, #C6, #6C, #38, #38, #6C, #C6, #00		; 88 X
			db #CC, #CC, #CC, #78, #30, #30, #78, #00		; 89 Y
			db #FE, #C6, #8C, #18, #32, #66, #FE, #00		; 90 Z
			db #78, #60, #60, #60, #60, #60, #78, #00		; 91 [
			db #C0, #60, #30, #18, #0C, #06, #02, #00		; 92 backslash
			db #78, #18, #18, #18, #18, #18, #78, #00		; 93 ]
			db #10, #38, #6C, #C6, #00, #00, #00, #00		; 94 ^
			db #00, #00, #00, #00, #00, #00, #00, #FF		; 95 _
			db #30, #30, #18, #00, #00, #00, #00, #00		; 96 `
			db #00, #00, #78, #0C, #7C, #CC, #76, #00		; 97 a
			db #E0, #60, #60, #7C, #66, #66, #DC, #00		; 98 b
			db #00, #00, #78, #CC, #C0, #CC, #78, #00		; 99 c
			db #1C, #0C, #0C, #7C, #CC, #CC, #76, #00		; 100 d
			db #00, #00, #78, #CC, #FC, #C0, #78, #00		; 101 e
			db #38, #6C, #60, #F0, #60, #60, #F0, #00		; 102 f
			db #00, #00, #76, #CC, #CC, #7C, #0C, #F8		; 103 g
			db #E0, #60, #6C, #76, #66, #66, #E6, #00		; 104 h
			db #30, #00, #70, #30, #30, #30, #78, #00		; 105 i
			db #0C, #00, #0C, #0C, #0C, #CC, #CC, #78		; 106 j
			db #E0, #60, #66, #6C, #78, #6C, #E6, #00		; 107 k
			db #70, #30, #30, #30, #30, #30, #78, #00		; 108 l
			db #00, #00, #CC, #FE, #FE, #D6, #C6, #00		; 109 m
			db #00, #00, #F8, #CC, #CC, #CC, #CC, #00		; 110 n
			db #00, #00, #78, #CC, #CC, #CC, #78, #00		; 111 o
			db #00, #00, #DC, #66, #66, #7C, #60, #F0		; 112 p
			db #00, #00, #76, #CC, #CC, #7C, #0C, #1E		; 113 q
			db #00, #00, #DC, #76, #66, #60, #F0, #00		; 114 r
			db #00, #00, #7C, #C0, #78, #0C, #F8, #00		; 115 s
			db #10, #30, #7C, #30, #30, #34, #18, #00		; 116 t
